	// Build SQL with placeholders
	sqlStr := fmt.Sprintf(`SELECT entry_no, reference_type, reference_entry_no, posting_date, entry_type, document_date FROM "%s" WHERE 1=1 AND entry_no = ?`, tableName)

	// Convert placeholders for PostgreSQL
	sqlStr = t.convertPlaceholders(sqlStr, len(args))
	sqlStr += t.forUpdate()

	err := t.exec().QueryRow(sqlStr, args...).Scan(
		&entry_noVal,
		&reference_typeInt,
		&reference_entry_noVal,
		&posting_dateNull,
		&entry_typeInt,
		&document_dateNull,
	)

	if err != nil {
		if err == sql.ErrNoRows {
			// Record not found - this is not an error, just return false
			return false
		}
		// Actual database error
		fmt.Printf("Error: Failed to get BOM_Ledger_Entry: %v\n", err)
		return false
	}

	// Populate fields
	t.Entry_no = entry_noVal
	t.Reference_type = BOMLedgerEntryReference_type(reference_typeInt)
